def link_existing_entries(apps, schema_editor):
    """すでにある半券を、作品名が一致する作品に結びつける（Work.match と同じ決まり）。"""
    Entry = apps.get_model("hanken", "Entry")
    Work = apps.get_model("hanken", "Work")
    for e in Entry.objects.filter(work__isnull=True):
        same = Work.objects.filter(title__iexact=e.title.strip())
        w = same.filter(kind=e.kind).first() or same.first()
        if w:
            e.work = w
            e.save(update_fields=["work"])


